import json


def validate(rec):
    if not isinstance(rec.get("id"), int) or not rec.get("name"):
        raise ValueError("bad record")


def save(path, rec):
    validate(rec)
    with open(path, "a") as fh:
        fh.write(json.dumps(rec) + "\n")

