import json


def validate(rec):
    if not isinstance(rec.get("id"), int) or not rec.get("name"):
        raise ValueError("bad record")


def save(path, rec):
    validate(rec)
    with open(path, "a") as fh:
        fh.write(json.dumps(rec) + "\n")


def save_many(path, recs):
    for rec in recs:
        validate(rec)
    with open(path, "a") as fh:
        for rec in recs:
            fh.write(json.dumps(rec) + "\n")


def import_lines(path, lines):
    with open(path, "a") as fh:
        for line in lines:
            fh.write(line.rstrip("\n") + "\n")
